-- Rollback for V224: restores tenant_id=1's aria:front-gate-create and
-- aria:dispatch-vehicle-details pages to their exact original body_json
-- (the content as it was before V224 changed the Flow Variant field/button
-- on front-gate-create, and added the flowVariantChoice selector on
-- dispatch-vehicle-details). Only the page-JSON side is reverted here — the
-- workflow_definition side (V223) is untouched.

UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
   SET pv.body_json = '{"kind":"layout","schemaVersion":2,"slug":"aria:front-gate-create","title":"Front Gate — Vehicle Intake","status":"published","version":1,"roles":["FrontGate","TenantAdmin"],"dataSources":[],"streams":[],"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"New Vehicle Intake","span":12,"subtitle":"Capture the vehicle at the gate, then Create Gate Pass to start the selected flow.","children":[{"kind":"Form","submitLabel":"","bindings":{"fields":[{"name":"loadingType","label":"Vehicle Movement Type","required":true,"type":"select","optionsSource":{"type":"entity","entity":"LoadingType","valueField":"code","labelField":"display_name"}},{"name":"flowVariant","label":"Flow Variant","type":"select","required":true,"placeholder":"Select Vehicle Movement Type first","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"FlowVariant","filter":{"field":"loading_type_code","op":"eq","value":"page:loadingType"},"select":["code","display_name"],"sort":[{"field":"display_name","dir":"asc"}]},"valueField":"code","labelField":"display_name"}},{"name":"vehicleNo","label":"Vehicle No","type":"text","required":true,"placeholder":"TN86J6790","uppercase":true,"pattern":"^[A-Z]{2}-?[0-9]{2}-?[A-Z]{1,2}-?[0-9]{4}$","patternError":"Enter valid vehicle number"},{"name":"vehicleCategory","label":"Vehicle Category","required":true,"type":"select","optionsSource":{"type":"entity","entity":"VehicleCategory","valueField":"code","labelField":"display_name"}}]},"children":[{"kind":"WorkflowActionButton","label":"Create Gate Pass","action":"workflow.transition","workflowCode":"{{form.flowVariant}}","targetState":"GATE_PASS_CREATED","trigger":"page.submitted","color":"primary","onSuccessOpen":{"page":"aria:gate-pass-slip","lookupEntity":"GatePass","lookupField":"workflow_instance_id","param":"id"}}]}]}]}]}'
 WHERE pd.code = 'aria:front-gate-create' AND pd.tenant_id = 1;

UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
   SET pv.body_json = '{"kind":"layout","schemaVersion":2,"dataSources":[{"id":"dispatchQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:dispatch-vehicle-details"}],"layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"Dispatch","dataSource":"dispatchQueue","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"secondLineFields":["gpNumber","flowVariantCode"]}]},{"kind":"Section","title":"Vehicle & Dispatch Details","fields":[{"kind":"FormField","type":"select","name":"vehicleNo","label":"Vehicle Number","required":true,"placeholder":"Select vehicle awaiting dispatch entry","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"Dispatch"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","vehicle_no"],"sort":[{"field":"vehicle_no","dir":"asc"}]},"valueField":"vehicle_no","labelField":"vehicle_no"},"onChangeFill":{"flowVariantCode":"flow_variant_code","loadingType":"loading_type","instanceId":"workflow_instance_id"}},{"kind":"FormField","type":"select","name":"ownershipType","label":"Ownership","options":["OWN VEHICLE","HIRED VEHICLE"]},{"kind":"FormField","type":"text","name":"driverName","label":"Driver Name"},{"kind":"FormField","type":"text","name":"driverPhone","label":"Driver Contact","pattern":"^[0-9]{10}$","patternError":"Enter a valid 10-digit phone number","maxLength":10,"digitsOnly":true},{"kind":"FormField","type":"text","name":"brokerName","label":"Broker Details","visibleWhen":"#form.flowVariantCode == 'M10.TankerOutbound' || #form.flowVariantCode == 'M10.TankerInbound' || #form.flowVariantCode == 'M10.PackUnload'"},{"kind":"FormField","type":"text","name":"invoiceNo","label":"Invoice No","visibleWhen":"#form.flowVariantCode == 'M10.TankerOutbo