kind":"FormField","type":"text","name":"transportName","label":"Transport Name","visibleWhen":"#form.flowVariantCode == 'M10.PackLoading' || #form.flowVariantCode == 'M10.FGLoading' || #form.flowVariantCode == 'M10.TankerOutbound'"},{"kind":"FormField","type":"textarea","name":"packingFgStockDetails","label":"Packing / FG Stock Details","visibleWhen":"#form.flowVariantCode == 'M10.PackLoading' || #form.flowVariantCode == 'M10.FGLoading' || #form.flowVariantCode == 'M10.PackUnload'"},{"kind":"FormField","type":"number","name":"invoiceReturnCount","label":"Invoice Stock Return Count","visibleWhen":"#form.flowVariantCode == 'M10.ReturnStockIn'"},{"kind":"FormField","type":"number","name":"boxWeightKg","label":"Box Weight (kg)","visibleWhen":"#form.flowVariantCode == 'M10.ReturnStockIn'"},{"kind":"FormField","type":"text","name":"oilType","label":"Oil Type","visibleWhen":"#form.flowVariantCode == 'M10.ReturnStockIn'"},{"kind":"FormField","type":"text","name":"flowVariantCode","label":"Flow Variant","disabled":true},{"kind":"FormField","type":"text","name":"loadingType","label":"Loading Type","disabled":true},{"kind":"WorkflowActionButton","label":"Save Vehicle Details","action":"workflow.transition","instanceId":"{{form.instanceId}}","variant":"primary"}]}],"entity":"DispatchVehicleDetail"}'
 WHERE pd.code = 'aria:dispatch-vehicle-details' AND pd.tenant_id = 1;
